import sys
import json
import heapq

try:
    if 'input_data' in globals():
        params = input_data
    else:
        params = json.loads(sys.argv[1])

    map_id = params.get('map_id')
    start_x = int(params.get('start_x'))
    start_y = int(params.get('start_y'))
    end_x = int(params.get('end_x'))
    end_y = int(params.get('end_y'))

    solid_coords = set()

    # Define obstacles for 1F (Map '0_59')
    if map_id == '0_59':
        # Cavern borders (Column 1 and Row 1 are solid walls)
        for y in range(0, 41):
            solid_coords.add((1, y))
        for x in range(0, 41):
            solid_coords.add((x, 1))

        # Column 12 & 13 central vertical rock wall (Row 16-19 are the bypass corridor!)
        # Rows 5 to 15 are completely solid rock walls
        for y in range(5, 16):
            solid_coords.add((12, y))
            solid_coords.add((13, y))

        # Row 20/21 is a platform height boundary (solid rock barrier)
        for x in range(0, 41):
            solid_coords.add((x, 20))

        # Column 16 is a solid rock wall on Rows 29 to 35
        for y in range(29, 36):
            solid_coords.add((16, y))

        # Columns 21-23 on Row 26 are impassable light-blue rock walls
        for x in range(21, 24):
            solid_coords.add((x, 26))

        # Column 19 is a solid wall on Rows 28, 30, 31, and 32
        for row_y in [28, 30, 31, 32]:
            solid_coords.add((19, row_y))

        # Row 19 platform boundary rock barrier at (6, 19)
        solid_coords.add((6, 19))

        # Defeated trainers (still solid overworld sprites)
        solid_coords.add((5, 6))   # Hiker
        solid_coords.add((7, 22))  # Bug Catcher
        solid_coords.add((16, 22)) # Lass
        solid_coords.add((30, 4))  # Lass Miriam
        solid_coords.add((30, 27)) # Bug Catcher
        solid_coords.add((24, 29)) # Super Nerd
        solid_coords.add((12, 16)) # Youngster

    # Define obstacles for B1F (Map '0_60')
    elif map_id == '0_60':
        for x in range(0, 41):
            for y in range(0, 41):
                in_horizontal_corridor = (5 <= x <= 21) and (16 <= y <= 17)
                in_vertical_corridor = (x == 5) and (5 <= y <= 17)
                in_ne_pocket = (21 <= x <= 27) and (5 <= y <= 13)

                if (in_horizontal_corridor or in_vertical_corridor or in_ne_pocket):
                    if (x, y) in [(25, 12), (25, 13), (9, 26)]:
                        solid_coords.add((x, y))
                else:
                    solid_coords.add((x, y))

    # Define obstacles for B2F (Map '0_61')
    elif map_id == '0_61':
        for y in range(15, 19):
            solid_coords.add((24, y))
        solid_coords.add((25, 12))
        for x in [29, 30]:
            for y in range(12, 15):
                solid_coords.add((x, y))
        solid_coords.add((24, 15))
        solid_coords.add((25, 15))
        for x in range(28, 32):
            solid_coords.add((x, 15))
        for x in range(24, 34):
            solid_coords.add((x, 11))
        for x in [27, 28, 29, 32, 33]:
            solid_coords.add((x, 21))
        solid_coords.add((29, 17))
        solid_coords.add((15, 24))
        solid_coords.add((29, 8))
        for x in range(0, 41):
            solid_coords.add((x, 19))
            solid_coords.add((x, 28))
            solid_coords.add((x, 20))

    # A* algorithm
    def astar(start, end):
        queue = []
        heapq.heappush(queue, (0, start, []))
        visited = set()

        while queue:
            cost, current, path = heapq.heappop(queue)

            if current == end:
                return path

            if current in visited:
                continue
            visited.add(current)

            cx, cy = current
            neighbors = [
                ((cx, cy - 1), 'Up'),
                ((cx, cy + 1), 'Down'),
                ((cx - 1, cy), 'Left'),
                ((cx + 1, cy), 'Right')
            ]

            for n_pos, action in neighbors:
                nx, ny = n_pos
                if nx < 0 or nx > 40 or ny < 0 or ny > 40:
                    continue
                if n_pos in solid_coords:
                    continue

                new_path = path + [action]
                heuristic = abs(nx - end_x) + abs(ny - end_y)
                heapq.heappush(queue, (len(new_path) + heuristic, n_pos, new_path))

        return None

    path = astar((start_x, start_y), (end_x, end_y))
    if path:
        print(json.dumps(path))
    else:
        print(json.dumps([]))

except Exception as e:
    print(json.dumps({"error": str(e)}))
